<?php
if (!defined('ABSPATH')) exit;

/* Twenty additional store-owned evergreen guides. The copy is intentionally
 * practical and model-neutral: product facts belong to the product record,
 * while this journal helps visitors make a better shortlist. */
add_action('init', function () {
    if (get_option('bhc_editorial_pack_v2_done')) return;

    $posts = [
        ['راهنمای خرید ماشین ظرفشویی برای خانواده‌های ایرانی', 'برای انتخاب ماشین ظرفشویی باید ظرفیت، ابعاد نصب، برنامه‌های شست‌وشو و دسترسی به خدمات را هم‌زمان بررسی کنید.', ['تعداد نفرات و عادت شست‌وشوی خانواده را به ظرفیت اسمی تبدیل کنید.','محل ورود آب، خروجی فاضلاب، برق و فضای بازشدن در را پیش از خرید اندازه بگیرید.','برنامه‌های کوتاه، شست‌وشوی اقتصادی و امکان تنظیم سبدها را با نیاز روزمره مقایسه کنید.']],
        ['تفاوت کولر گازی اینورتر و معمولی چیست؟', 'انتخاب کولر گازی زمانی درست است که ظرفیت سرمایش با متراژ، نورگیری و شرایط واقعی اتاق هماهنگ باشد.', ['متراژ تنها معیار نیست؛ ارتفاع سقف، پنجره‌ها و آفتاب‌گیر بودن فضا را هم در نظر بگیرید.','نوع کمپرسور، صدای کار و امکان سرویس دوره‌ای را در کنار مصرف انرژی بررسی کنید.','پیش از خرید، مسیر نصب یونیت داخلی و خارجی و محدودیت‌های ساختمان را مشخص کنید.']],
        ['جاروبرقی کیسه‌ای یا مخزن‌دار؛ کدام انتخاب بهتری است؟', 'مقایسه جاروبرقی کیسه‌ای و مخزن‌دار باید بر اساس تعداد دفعات نظافت، حساسیت به گردوغبار و هزینه نگهداری انجام شود.', ['کیسه‌ای‌ها برای تخلیه کم‌گردوغبار مناسب‌اند؛ مخزن‌دارها هزینه خرید کیسه را حذف می‌کنند.','نوع فیلتر، دسترسی به فیلتر جایگزین و روش شست‌وشوی مخزن را بررسی کنید.','وزن، شعاع عملکرد، صدای کار و سری‌های همراه در استفاده روزانه اثر زیادی دارند.']],
        ['قبل از خرید مایکروویو چه نکاتی را بررسی کنیم؟', 'مایکروویو مناسب فقط به ظاهر یا توان خلاصه نمی‌شود؛ فضای نصب، ظرفیت داخلی و شیوه استفاده روزانه مهم‌ترند.', ['ابعاد بیرونی و فضای گردش هوا را با کابینت و محل نصب تطبیق دهید.','ظرفیت را با اندازه ظرف‌هایی که معمولاً استفاده می‌کنید بسنجید.','برنامه‌های گرم‌کردن، یخ‌زدایی، گریل و نحوه تمیزکردن محفظه را مقایسه کنید.']],
        ['راهنمای انتخاب فر توکار برای آشپزخانه', 'فر توکار باید با ابعاد کابینت، نوع پخت موردنیاز و امکاناتی که واقعاً استفاده می‌کنید هماهنگ باشد.', ['عرض، عمق نصب و فاصله تهویه را از نقشه کابینت یا نصاب بگیرید.','تعداد حالت‌های پخت، دقت کنترل دما و تمیزکاری داخلی را با سبک آشپزی خود مقایسه کنید.','مسیر برق، محل قرارگیری پنل و دسترسی ایمن به در فر را پیش از سفارش بررسی کنید.']],
        ['تلویزیون مناسب فیلم و بازی را چگونه انتخاب کنیم؟', 'اندازه صفحه فقط یکی از عوامل انتخاب تلویزیون است؛ نور محیط، فاصله تماشا، ورودی‌ها و سرعت تصویر هم مهم‌اند.', ['فاصله نشستن و عرض دیوار را قبل از انتخاب اندازه صفحه اندازه‌گیری کنید.','برای بازی و محتوای سریع، تأخیر ورودی، نرخ نوسازی و تعداد پورت‌ها را بررسی کنید.','روشنایی محیط، بازتاب صفحه و جای عبور کابل را در تصمیم نهایی لحاظ کنید.']],
        ['راهنمای خرید تصفیه هوا برای اتاق خواب', 'تصفیه هوا زمانی مفیدتر است که ظرفیت دستگاه با حجم اتاق و برنامه استفاده روزانه هماهنگ باشد.', ['حجم اتاق و میزان باز و بسته‌شدن پنجره‌ها را پیش از انتخاب مشخص کنید.','نوع فیلتر، هزینه تعویض و روش اعلام زمان سرویس را بررسی کنید.','صدای کار در حالت شب، مصرف برق و امکان جابه‌جایی دستگاه را جدی بگیرید.']],
        ['اتو بخار یا اتو مخزن‌دار؛ انتخاب حرفه‌ای برای خانه', 'انتخاب اتو به حجم لباس‌ها، فضای نگهداری و نیاز به بخار پیوسته بستگی دارد؛ عدد توان به‌تنهایی کافی نیست.', ['کفی روان، تنظیم بخار و دسترسی به مخزن آب را با دفعات اتوکشی مقایسه کنید.','برای حجم بالا، ظرفیت مخزن و روش رسوب‌زدایی را قبل از خرید بررسی کنید.','طول سیم، وزن اتو و ایمنی خاموشی خودکار در استفاده روزمره اهمیت دارند.']],
        ['راهنمای انتخاب سرخ‌کن بدون روغن', 'برای خرید سرخ‌کن بدون روغن، ظرفیت واقعی سبد، برنامه‌ها، تمیزکاری و فضای موردنیاز روی کابینت را بررسی کنید.', ['ظرفیت را بر اساس تعداد نفرات و اندازه وعده معمول خانواده بسنجید.','جداشدن سبد، شست‌وشوی آسان و دسترسی به قطعات مصرفی را بررسی کنید.','توان، بازه دما، زمان‌سنج و امکان مشاهده روند پخت را با نیاز خود تطبیق دهید.']],
        ['نکات نگهداری یخچال و فریزر برای کارکرد بهتر', 'نگهداری درست یخچال به تنظیم دما محدود نیست؛ فاصله تهویه، چیدمان مواد و نظافت دوره‌ای هم مهم است.', ['فضای آزاد پشت و اطراف دستگاه را مطابق دستور نصب حفظ کنید.','مواد غذایی را طوری بچینید که مسیر گردش هوا و بسته‌شدن کامل در مختل نشود.','لاستیک در، مسیر تخلیه و بخش‌های قابل شست‌وشو را در برنامه منظم بررسی کنید.']],
        ['چگونه صدای جاروبرقی را هنگام خرید مقایسه کنیم؟', 'صدای ادراک‌شده جاروبرقی به موتور، مسیر هوا، برس و سطح زمین وابسته است؛ مقایسه باید در کنار دیگر مشخصات انجام شود.', ['عدد اعلام‌شده صدا را با نوع استفاده و زمان نظافت خود مقایسه کنید.','وجود حالت کم‌صدا و تغییر قدرت مکش برای خانه‌های کوچک مفید است.','لرزش بدنه، صدای برس و کیفیت چرخ‌ها را در ویدیو یا بررسی حضوری جدی بگیرید.']],
        ['چک‌لیست نصب ماشین لباسشویی', 'بخش مهمی از عملکرد ماشین لباسشویی به نصب تراز، اتصال درست آب و رعایت فضای اطراف دستگاه وابسته است.', ['مسیر حمل، عرض درها و عمق جای نصب را پیش از تحویل کنترل کنید.','تراز بودن پایه‌ها و اتصال ایمن شلنگ ورودی و خروجی را به نصاب بسپارید.','فضای کافی برای بازشدن در، گردش هوا و دسترسی به شیر آب باقی بگذارید.']],
        ['راهنمای کاهش مصرف انرژی لوازم خانگی', 'مصرف انرژی فقط به برچسب محصول وابسته نیست؛ اندازه درست، شیوه استفاده و نگهداری منظم هم اثرگذارند.', ['ظرفیت دستگاه را با نیاز واقعی انتخاب کنید تا دستگاه نیمه‌خالی یا بیش‌ازحد پر کار نکند.','فیلترها، درزگیرها و مسیرهای گردش هوا را طبق برنامه تمیز کنید.','برنامه اقتصادی را زمانی استفاده کنید که با حجم و نوع کار دستگاه سازگار باشد.']],
        ['برای خانه جدید چه لوازم خانگی را اول بخریم؟', 'خرید مرحله‌ای برای خانه جدید باید از نیازهای روزمره و محدودیت فضا شروع شود، نه از فهرست‌های عمومی و طولانی.', ['ابعاد آشپزخانه، تعداد ساکنان و الگوی پخت‌وپز را در یک فهرست کوتاه ثبت کنید.','اقلام ضروری را از گزینه‌های تکمیلی جدا کنید و بودجه را برای نصب و لوازم همراه کنار بگذارید.','قبل از نهایی‌کردن هر کالا، مسیر ورود، جای نصب و امکان خدمات را بررسی کنید.']],
        ['ظرفیت واقعی لوازم خانگی را چگونه بسنجیم؟', 'عدد ظرفیت زمانی معنا دارد که با ابعاد داخلی، نوع استفاده و فضای نصب کنار هم دیده شود.', ['ظرفیت اسمی را با اندازه سبد، دیگ یا محفظه واقعی مقایسه کنید.','برای خانواده، مقدار استفاده در هر نوبت و فاصله بین نوبت‌ها را در نظر بگیرید.','ابعاد بیرونی، وزن و فضای لازم برای بازشدن در را از مشخصات ظرفیت جدا بدانید.']],
        ['راهنمای بررسی گارانتی و خدمات پس از فروش', 'پیش از خرید، باید بدانید کالا با چه شرایطی تحویل می‌شود و برای نصب، سرویس یا پیگیری ایراد از چه مسیر داخلی فروشگاه استفاده می‌کنید.', ['نام کامل مدل، رنگ و اقلام همراه را با سفارش تطبیق دهید.','شرایط نصب، محدوده خدمات و مدارک لازم را قبل از تحویل بپرسید.','رسید، شماره سفارش و گزارش تحویل را تا پایان دوره پیگیری نگه دارید.']],
        ['تلویزیون مناسب اتاق روشن را چگونه انتخاب کنیم؟', 'در اتاق‌های پرنور، کنترل بازتاب و روشنایی صفحه به اندازه وضوح تصویر اهمیت دارد.', ['جهت پنجره‌ها و محل تابش مستقیم را پیش از انتخاب جای تلویزیون مشخص کنید.','صفحه‌ای را انتخاب کنید که بازتاب مزاحم و زاویه دید قابل‌قبولی برای خانواده داشته باشد.','روشنایی زیاد را با تنظیمات تصویر و فاصله تماشا اشتباه نگیرید.']],
        ['راهنمای انتخاب هود آشپزخانه', 'هود مناسب باید با عرض اجاق، مسیر خروجی و اندازه آشپزخانه هماهنگ باشد تا مکش و صدای کار قابل‌قبول بماند.', ['عرض هود را با اجاق و فضای کابینت تطبیق دهید.','مسیر خروج هوا، امکان نصب و فضای لازم برای فیلترها را بررسی کنید.','سرعت‌های مکش، صدای کار و تمیزکردن فیلتر را در استفاده واقعی بسنجید.']],
        ['راهنمای انتخاب پنکه و تهویه برای فضای کوچک', 'برای فضای کوچک، اندازه، صدای کار، امکان تنظیم جهت و مصرف برق از قدرت خام مهم‌تر است.', ['محل قرارگیری و فاصله ایمن از مسیر رفت‌وآمد را اندازه بگیرید.','تنظیم سرعت، نوسان، ارتفاع و کنترل دستگاه را با نیاز اتاق مقایسه کنید.','برای خواب یا کار، صدای حالت کم و پایداری پایه را جدی بگیرید.']],
        ['چک‌لیست خرید لوازم خانگی نو و آکبند', 'پیش از تحویل کالای نو، تطبیق مدل و سلامت ظاهری از هر توضیح تبلیغاتی مهم‌تر است.', ['پلاک مدل، رنگ، شماره سفارش و اقلام همراه را با فاکتور تطبیق دهید.','بدنه، نمایشگر، درها، کابل و بسته‌بندی را پیش از امضای رسید بررسی کنید.','هر مغایرت را همان زمان با تصویر و توضیح روشن در گزارش تحویل ثبت کنید.']],
    ];

    $term = get_term_by('name', 'راهنمای خرید', 'category');
    if (!$term) $term = wp_insert_term('راهنمای خرید', 'category');
    $term_id = is_wp_error($term) ? 0 : (int)($term->term_id ?? $term['term_id'] ?? 0);
    $created = 0;
    foreach ($posts as $row) {
        $existing = get_posts(['post_type'=>'post','post_status'=>['publish','draft'],'title'=>$row[0],'numberposts'=>1,'fields'=>'ids']);
        if ($existing) continue;
        $html = '<p>'.esc_html($row[1]).'</p><h2>نکته‌های کاربردی</h2><ul>';
        foreach ($row[2] as $item) $html .= '<li>'.esc_html($item).'</li>';
        $html .= '</ul><h2>جمع‌بندی</h2><p>برای انتخاب دقیق، اطلاعات همان مدل، ابعاد فضای نصب و نیاز واقعی خانه را کنار هم بگذارید. اگر بخشی از مشخصات یا وضعیت کالا روشن نیست، پیش از خرید از پشتیبانی بهاران‌هوم راهنمایی بگیرید.</p>';
        $id = wp_insert_post(['post_title'=>$row[0],'post_content'=>$html,'post_status'=>'publish','post_type'=>'post','post_excerpt'=>$row[1],'comment_status'=>'closed'], true);
        if (is_wp_error($id) || !$id) continue;
        update_post_meta($id, '_bhb_editorial_review', 'approved');
        update_post_meta($id, '_bhc_seo_title', $row[0].' | راهنمای بهاران‌هوم');
        update_post_meta($id, '_bhc_seo_description', $row[1].' راهنمای کاربردی بهاران‌هوم برای مقایسه و انتخاب آگاهانه لوازم خانه.');
        if ($term_id) wp_set_post_categories($id, [$term_id]);
        $created++;
    }
    update_option('bhc_editorial_pack_v2_done', ['created'=>$created,'at'=>current_time('mysql')], false);
}, 29);
